      "reason": "PM is the explicitly named participant responsible for organizing, not merely a role mentioned in context.",
      "sources": [
        {"quote": "PM must organize", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "n2",
      "verdict": "SUPPORT",
      "reason": "The main predicate is organizing, and “must” explicitly makes it REQUIRED.",
      "sources": [
        {"quote": "PM must organize creation", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "n3",
      "verdict": "SUPPORT",
      "reason": "Creation is the production event embedded as the complement of organizing. The source does not independently assign a creator or separately modalize this event.",
      "sources": [
        {"quote": "must organize creation of incident-guide.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "n4",
      "verdict": "SUPPORT",
      "reason": "The named file is the intended generated result of creation, rather than an existing input. This does not assert that creation has already occurred.",
      "sources": [
        {"quote": "creation of incident-guide.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "n5",
      "verdict": "SUPPORT",
      "reason": "Detection is a named section of the intended file, represented as output content rather than an instruction to perform detection.",
      "sources": [
        {"quote": "incident-guide.md with sections “Detection” and “Recovery”", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "n6",
      "verdict": "SUPPORT",
      "reason": "Recovery is a named section of the intended file. Its title does not authorize or require recovery execution.",
      "sources": [
        {"quote": "incident-guide.md with sections “Detection” and “Recovery”", "clause_id": "c1", "occurrence": 0, "context_anchor": null},
        {"quote": "No recovery action may actually be performed.", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "n7",
      "verdict": "SUPPORT",
      "reason": "The sentence explicitly prohibits actual performance of any recovery action. FORBIDDEN and NEGATED represent this prohibition without asserting an executed event or assigning an actor.",
      "sources": [
        {"quote": "No recovery action may actually be performed.", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r1",
      "verdict": "SUPPORT",
      "reason": "PM is the grammatical and participating agent of organizing. This relation does not make PM the creator of the file.",
      "sources": [
        {"quote": "PM must organize creation", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r2",
      "verdict": "SUPPORT",
      "reason": "Structural containment is supported because creation is the complement within the organizing event. This supports PART_OF as complement containment, not a claim that organizing itself executes creation.",
      "sources": [
        {"quote": "organize creation", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r3",
      "verdict": "SUPPORT",
      "reason": "The creation event has the named file as its intended result.",
      "sources": [
        {"quote": "creation of incident-guide.md", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r4",
      "verdict": "SUPPORT",
      "reason": "The with-sections phrase explicitly places the Detection section within the intended file.",
      "sources": [
        {"quote": "incident-guide.md with sections “Detection” and “Recovery”", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r5",
      "verdict": "SUPPORT",
      "reason": "The with-sections phrase explicitly places the Recovery section within the intended file.",
      "sources": [
        {"quote": "incident-guide.md with sections “Detection” and “Recovery”", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r6",
      "verdict": "SUPPORT",
      "reason": "“And” explicitly conjoins the two required section names; neither is presented as an alternative.",
      "sources": [
        {"quote": "sections “Detection” and “Recovery”", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    },
    {
      "candidate_id": "r7",
      "verdict": "SUPPORT",
      "reason": "The prohibition applies at task scope to actual recovery-action performance, without an actor-specific exception or stated condition.",
      "sources": [
        {"quote": "No recovery action may actually be performed.", "clause_id": "c1", "occurrence": 0, "context_anchor": null}
      ]
    }
